task('p13-body','第十三段：动作反映心理',13,5,2,'objective',['从哪里可以看出“我”和蒋妍很恐惧？（找第13段）','根据解释，从课文中找出相应的词语：奇异；奇特。'],
'“蜷缩在被子里瑟瑟发抖”表现蒋妍害怕。对应词语是“诡异”。',
'蜷缩、发抖是具体动作，结合刚才的经历理解恐惧。课文没有写她冷得发抖；“身体描写”无需另立成一种固定考试术语。', ['动作与恐惧联系','找出诡异'],['找蒋妍在被子里的反应。','结合门外女生出现后的语境，而不是只看“发抖”。'], '课本预习二第3题；恐惧取证题；修订旧Q10',
 evidence=[ev('加入蒋妍的动作原句',[13],['蜷缩'])],blanks=[b('strange','奇异、奇特，课文写作','诡异')],bank=['诡异','隐约','恐惧'],reject='把身体动作机械当成新描写类别；没有依据地说她发烧或冷。')
task('p16-common','第十六段：开始发现共同点',16,5,2,'objective',['“你也喜欢读鬼故事？”中的“也”，让我们发现了什么？','结合上下文，推测第14段“恐怖”的意思。'],
'“也”说明“我”同样喜欢读鬼故事，两人有共同爱好。“恐怖”指令人害怕、胆战心惊。',
'由“也”可推断“我”也喜欢鬼故事；第16段的回答确认蒋妍的爱好。共同话题帮助她们继续交流。', ['共同爱好','根据“也”作推断','恐怖的意思'],['是谁说“你也”？','先找蒋妍的爱好，再想“也”多说明了谁。'], '课本预习一第3题；教参关系变化；旧Q9的前置定位',
 range=[14,16],checks=[c('common','“也”最能说明什么？',['蒋妍曾读过“我”借给她的书','“我”也有阅读鬼故事的爱好','“我”已经查明门外女生身份','蒋妍以前已和“我”讨论此事'],1,['借书在第17段，不能提前。','“也”表示两人有相同爱好。','真相还没有揭开。','原文此前写两人缺乏交流。'])],oral=[['“恐怖”在这里是什么意思？','令人感到很害怕。蒋妍以为遇到恐怖事件，是人物当时的理解。']])
task('p17-change','第十七段：讨厌鬼为什么不见了',17,6,2,'objective',['阅读课文，说一说“我”心中的“讨厌鬼”是谁，为什么这个“讨厌鬼”最后不见了。','根据解释，从课文中找出相应的词语：整夜。'],
'“讨厌鬼”指“我”原先讨厌的蒋妍。两人因共同的恐惧开始交流，发现彼此有共同点；蒋妍也为之前的事道歉。“我”改变看法，不再讨厌她，还主动借书给她。“通宵”就是整夜。',
'“不见了”是厌恶的感受消失，不是人离开了。只写“借书”是结果，仍要解释交流、了解与道歉怎样改善关系。', ['指蒋妍','交流发现共同点','蒋妍道歉','“我”改变看法'],['先区分蒋妍与门外女生。','在借书之前，两人做了什么、发现什么？'], '课本预习三、预习二第4题；教参；旧Q2、Q9、Q18重写',
 blanks=[b('who','“讨厌鬼”指','原先令“我”讨厌的蒋妍'),b('why','聊一夜后，两人','发现共同点'),b('sorry','接着','蒋妍为之前的事道歉'),b('night','“通宵”表示','整夜')],bank=['发现共同点','整夜','原先令“我”讨厌的蒋妍','蒋妍为之前的事道歉','走错宿舍的新同学','“我”向新同学道歉'],
 oral=[['为什么“我”会和蒋妍聊一通宵？','共同恐惧打开了话题，又发现都喜欢鬼故事及其他共同点，所以逐渐谈得投机。']],reject='说讨厌鬼也指门外女生；说两人互相道歉；把不见了理解为搬走。')
task('p18-truth','第十八段：真相为什么略写',18,7,2,'objective',['闹鬼的真相是什么？为什么这个部分写得很简略？'],
'门外女生是住在楼上的新同学，那天走错了宿舍。文章重点是两人通过交流改善关系；真相只是补充事情的完整性，所以简略交代。',
'详略取决于与主题的关系。真相让读者明白发生了误会，但文章并不是要详细追查一个鬼故事。', ['新同学走错宿舍','补充完整性','与交流主题关系较小所以略写'],['看“原来”后面的解释。','比较文章花较多篇幅写的是什么变化。'], '课本第18段旁注；教参2.2第18—19段',
 checks=[c('brief','为什么真相只作简略交代？',['真相已无从考证，只能略去经过','新同学没有说话，作者无法介绍','补足误会来由，把篇幅留给关系变化','真相揭开太早，导致前文失去紧张'],2,['原文明确交代了身份和走错宿舍。','第18段已有身份信息，不是无法介绍。','符合本文主题和叙事重点。','真相在结尾出现，并非过早。'])],reject='只说“不重要”而不联系主题；把门外人写成鬼。')
task('p18-beauty','第十八段：惊悚而美丽',18,7,2,'subjective',['作者为什么说新同学走错宿舍是一个“惊悚而美丽的误会”？'],
'“惊悚”指两人把走错宿舍的女生误当作鬼，感到害怕；“美丽”指这个误会促使两人交流，发现共同点、化解隔阂，关系改善。所以事情的过程吓人，带来的结果却美好。',
'分别解释两个词指向什么，再连起来理解。“美丽”形容误会带来的结果，不是说新同学外貌漂亮。', ['惊悚：误会使两人恐惧','美丽：交流后关系改善','解释过程与结果的不同'],['“惊悚”说当时感受，“美丽”说什么结果？','回看第17段，误会之后两人发生了什么变化？'], '教参第18—19段；旧Q19整合',
 range=[9,18],fields=[f('meaning','解释两个关键词','“惊悚”指……；“美丽”指……。这个误会……。')],scoreGuide='建议3分：误会带来恐惧1分；促成交流与了解1分；关系改善这一美好结果1分。只写“很可怕又很好”没有具体意义。',reject='把美丽解释成女生漂亮；只解释一半；没有说明交流与关系改善。')
task('p19-theme','第十九段：关键句与主题',19,8,2,'subjective',['识别文章中的关键句——一般是文中的抒情句和议论句。找出课文中的这一类关键句，结合内容理解文章的主题。'],
'抒情句可选“多么惊悚而美丽的误会啊！”；议论句是“其实，人与人相处，总会出现这样那样的问题。很多时候，只要多点交流，就可以解决这些问题，人们之间的关系也会变得更和谐。”主题：人与人相处需要多交流，增进了解、化解隔阂，使关系更和谐。',
'抒情句表达对误会美好结果的感慨，议论句由故事说出相处道理；第17段交流后关系改善，提供内容依据。感叹号只是线索，要看句子在表达感情还是讲道理。', ['取抒情句','完整议论句可连续加入两句','主题结合关系变化'],['先看第18段末句，再看第19段由故事转为道理的位置。','“其实”之后不只写这两个人，还谈什么？'], '课本阅读放大镜三；整合旧Q3—5、Q22',role='师生共构',
 scope='full',range=[1,19],conceptNotes=[['抒情句（expressing feelings）','直接表达对人或事的情感。例如“好漂亮的鸟蛋！”表达惊喜。'],['议论句（expressing a view）','对事情提出看法或道理。例如“相处时应顾及别人的需要。”'],['联系内容','找关键句后，解释课文中的关系变化怎样支持它。']],
 evidence=[ev('抒情句：先回看第18段',[18],['多么']),ev('议论句：第19段可连续加入两句',[19],['人与人相处','很多时候'],['人与人相处','很多时候'])],fields=[f('theme','主题与内容依据','文章告诉我们……。两人原本……，交流后……，所以……。')],scoreGuide='建议4分：关键句各1分；主题1分；联系交流前后关系变化1分。句子选择范围不同但意义准确，可接受；第1段也有抒情表达，但选结尾句更便于结合主题。',reject='把“真有恐怖事件”当事实；只写朋友要互助而未提交流；把交流说成保证解决一切问题。')
task('full-table','全文回看：内容与关系变化',19,9,3,'objective',['阅读课文，了解课文内容，完成主要内容和“我”与蒋妍的关系变化表。'],
'蒋妍晚睡早起，影响室友休息，“我”讨厌她；提醒后她没有改变，“我”吼起来，两人成了冤家；发生“恐怖事件”后两人开始交流，发现共同点，蒋妍道歉；“我”借恐怖小说给她，不再讨厌她。',
'把事情与关系放在一起看，因果才能完整。“一起害怕”只是起点，交流带来了解，才推动关系改善。', ['四阶段关系变化完整','事情与关系对应','蒋妍道歉不改成互相道歉'],['按第2、3—5、6—17、17段的顺序回看。','一行写发生什么，另一部分写关系怎样改变。'], '课本阅读放大镜二；整合旧Q1、Q2',scope='full',range=[1,19],
 blanks=[b('row1a','蒋妍晚睡早起，','影响室友休息'),b('row1b','“我”','讨厌蒋妍'),b('row2a','“我”和室友们','委婉提醒她尊重彼此作息'),b('row2b','提醒无效，“我”吼起来，两人成了','冤家'),b('row3a','宿舍发生','“恐怖事件”'),b('row3b','“我”和蒋妍','开始交流'),b('row3c','两人发现','彼此有许多共同点'),b('row3d','蒋妍','为之前的事情道歉'),b('row4a','“我”把','两本恐怖小说借给她'),b('row4b','“我”和蒋妍','关系改善，成为朋友')],bank=['冤家','开始交流','影响室友休息','两本恐怖小说借给她','彼此有许多共同点','讨厌蒋妍','关系改善，成为朋友','委婉提醒她尊重彼此作息','为之前的事情道歉','“恐怖事件”'],guide='按课本表格顺序点选；全篇读完后再统整。')
task('exclamation','语言运用：改成感叹句',19,9,3,'subjective',['根据提示，把下列句子改写成感叹句。','1. 你这么做很过分。（真）','2. 这店里的东西很便宜。（好）','3. 这里的景色很美丽。（多么）'],
'1. 你这么做真过分！\n2. 这店里的东西好便宜啊！\n3. 这里的景色多么美丽啊！',
'保留原句意思，用提示词增强语气。语气词可有合理变化；第1句也可写“你这么做真是太过分了！”不能只把句号换成感叹号却漏掉提示词。', ['保留句意','使用真／好／多么','感叹语气与标点恰当'],['看括号里指定的词。','把“很”换成提示词，再检查是否需要语气词。'], '课本阅读放大镜一三道原题',scope='full',
 conceptNotes=[['先比较','“景色很美丽。”平实陈述；“景色多么美丽啊！”表达更强的赞叹。']],fields=[f('sentences','依次写三句','1. ……\n2. ……\n3. ……')],scoreGuide='每句建议1分，共3分。提示词、句意与感叹语气须相符。接受合理语气词变化，由教师核对。',reject='漏提示词；改掉原意；误把所有感叹句都理解为愤怒。')
task('open-response','必做开放回应：交流为什么有用',19,10,3,'subjective',['作者认为：“很多时候，只要多点交流，就可以解决这些问题，人们之间的关系也会变得更和谐。”','你是否赞同这个看法？为什么？','说一说你和同学相处时曾遇到的问题，以及你是如何解决这个问题的。'],
'以下为虚构示范，不是学生个人经历：我赞同交流常能改善关系。因为把想法和困难说清楚，双方才知道怎样配合。例如小组合作时，有同学没有按时交稿，我先询问，得知他不清楚分工。我们重新确认任务和时间，后来顺利完成。交流让我们找到了原因，并落实调整，所以减少了误会。',
'立场—理由—例子—回扣。生活题写自己的真实经历，不照抄虚构示范。也可部分赞同或不赞同，但要解释范围和条件。交流之外，双方还应愿意顾及对方并改变行动。', ['明确看法','解释交流的作用或限制','具体相处问题和解决过程','说明例子怎样支持看法'],['先说清谁和谁遇到什么问题。','你们说清了什么？之后改变了什么行动？这怎样支持你的看法？'], '课本第19段旁注、读后说；整合旧Q23、Q24',required=True,scope='full',range=[1,19],
 concept='open',fields=[f('position','立场与理由','我……这个看法，因为……。'),f('example','自己的经历：问题与解决过程','曾经……；我／我们通过……；后来……。'),f('link','回扣：为什么这个例子支持你的看法','这说明……，因为交流使……；还需要……。')],scoreGuide='建议4分：立场1分；理由1分；具体问题与解决过程1分；解释例子与观点的联系1分。各点独立判断，不因立场不同扣分，不凭字数或关键词自动评分。',
 alternatives=['若没有愿意分享的个人经历，可先由教师安排口头私下交流；不要求虚构成自己的经历。','部分赞同示例：交流能澄清误解，但若双方不愿改变干扰别人的行为，单靠说话仍不够。必须用具体情境说明。'],reject='只说“交流很好”；只讲故事不解释；把所有问题都归为误会；捏造个人经历照抄示范。')

