lex={'憋':'勉强忍住，把话语或情绪压在心里。','勤奋':'努力而不懒惰。','不堪其扰':'不能忍受这种打扰。','刺眼':'光线强烈，使眼睛不舒服。','清晨':'早晨天刚亮的一段时间。','委婉':'说话温和含蓄，不直接生硬。','彼此':'你我双方，相互。','作息':'工作、学习和休息的安排。','始终':'从开始到最后，一直。','发泄':'把不满等情绪表达或释放出来。','忍无可忍':'再也无法忍受。','吼':'大声喊叫。','怒气冲冲':'十分生气的样子。','反驳':'说出理由，否定别人的意见。','彻底':'完全，毫无保留。','冤家':'本课形容关系不和、互不搭理的两人。','搭理':'理睬，与对方说话或回应。','抬头不见低头见':'形容经常见面。','共处一室':'一起待在同一个房间里。','仿佛':'好像，似乎。','凝固':'由流动状态变成固定状态；这里写气氛僵硬。','扭动':'转动。','缓缓':'慢慢地。','裂开一条缝':'这里指门慢慢打开，露出一道窄缝。','披散':'散开垂着，没有束起。','吭声':'出声，说话。','微微':'稍微，轻轻地。','仰起':'把头或脸抬起来。','扫':'这里指目光迅速看过。','古怪':'奇怪，不寻常。','随即':'紧接着就。','掩':'这里指关上门。','对视':'互相看着对方。','恐惧':'害怕。','鼓起勇气':'努力使自己有勇气去做事。','探出身':'把身体向外伸出一些。','空荡荡':'空空的，没有人或东西。','熄灯':'把灯关掉，使灯不亮。','颤抖':'不由自主地抖动；这里指声音因害怕而不稳。','诡异':'奇异、奇特，让人感到不寻常。','隐约':'看得或听得不很清楚。','蜷缩':'身体弯曲缩成一团。','瑟瑟发抖':'身体不停地轻轻抖动；本课表现害怕。','恐怖':'令人感到害怕、胆战心惊。','居然':'表示出乎意料。','打断':'使别人的话或正在做的事中途停下。','竟然':'表示出乎意料。','通宵':'整夜。','共同点':'彼此相同的地方。','道歉':'表示自己有错，请求原谅。','讨厌鬼':'本课是“我”对蒋妍的负面称呼。','惊悚':'令人惊惧、害怕。','误会':'对人或事情产生了错误的理解。','交流':'彼此交换意见、想法或感受。','和谐':'相处融洽、协调。'}
(O/'lexicon.js').write_text('window.LESSON_WORDS='+json.dumps({k:{'meaning':v}for k,v in lex.items()},ensure_ascii=False)+';\nwindow.WORD_ALIASES={};\n')
boundary=['全文依附件核对，共19段。第17段照课本录为“心中那个‘讨厌鬼’就不见了”，修正旧页多出的“早”字。','五张漫画原文件保持不变，以CSS画格视窗对应段落，完整原图另可回看。漫画第29格“我也坐了起来”、第28格“突然坐起身”等为画面演绎，课文没有写这些动作；第37格“早就不见了”也不同于课本“就不见了”。取证只依据左侧课文。','第14段“真有恐怖事件”是蒋妍当时的误认。第18段揭示来者是走错宿舍的新同学。不能把“鬼”当作真实事实。','旧页“讨厌鬼双关门外女生”“互相道歉”“冤家含亲近玩笑”等解释已修正。“我”与真实作者的身份关系无法由本文确定，删除该道猜测题。','原网址只有一份24题练习，被两个平台入口重复引用；新版保留原网址，替换旧练习并移除重复的课前预习入口。旧版仅用页面内存保存，没有发现localStorage持久记录，因此没有可迁移的旧答案。','完整保留已提供的预习一、二、三、旁注问题、阅读放大镜一至三、读后说及教参引导题的核心要求。教参未随附的活动本课后练习不伪造、不新增。']
schedule=[['第一课','50分钟','导入3；第1—5段图文和问题18；第6段夸张、动词效果14；第7—10段取证10；检查与词语5。书写：夸张作用一项。'],['第二课','50分钟','回读3；第11—16段声音、动作、共同点12；第17段变化7；第18段真相和句义12；第19段关键句与主题12；订正4。书写：句义、主题两项。'],['第三课','50分钟','回读5；内容与关系表10；感叹句8；开放回应独立构思和写答15；讨论比较与订正8；词语本整理4。书写：三句改写为一项、开放回应一项。']]
B=dict(goals=['依据原文理清两人从缺乏交流、互不搭理到成为朋友的过程。','通过眼神、动作、声音取证，解释恐惧及夸张、动词的表达作用。','借抒情句、议论句和情节理解主题，解释“惊悚而美丽”。','正确改写感叹句，并用具体经历说明交流为什么能改善关系或有什么限制。'],schedule=schedule,twoLesson='两课时各50分钟：第一课完成第1—13段，夸张作用保留一次书写；第二课完成第14—19段、统整和开放回应，保留“惊悚而美丽”与开放回应两项书写。感叹句改为口头逐句改写，主题采用教师共同整理，表格快速点选；省去重复全班汇报，不删原题或必做开放题。',sourceBoundary=boundary,difficulties=['“坏习惯”“冤家”“讨厌鬼”都有语境意义，不能机械套术语。','“不敢反驳”不能证明已服气；不把推测写成事实。','“交流”不只等于说话次数多，还涉及了解、道歉和改变。','作用题须把具体内容与关系连接，不能只报修辞名称。'],groups=10,steps=len(T),oldQuestions=24,paragraphMap=[dict(p=i+1,idea=ideas[i],panels=panels[i],tasks=[t['id']for t in T if t['focus']==[i+1]])for i in range(19)])
(O/'teaching-brief.json').write_text(json.dumps(B,ensure_ascii=False,indent=2))
print({'tasks':len(T),'words':len(lex),'groups':len(set(t['group']for t in T))})
